// Build structured OpenAI user prompt from lead enrichment data — 2026-06-19 UTC+5
const it = $json;
const cfg = $('config').first().json;

let pains = it.pain_points;
if (typeof pains === 'string') {
  try { pains = JSON.parse(pains); } catch (e) { pains = pains ? [pains] : []; }
}
if (!Array.isArray(pains)) pains = [];

const htmlSnippet = (it.scraped_html || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s{2,}/g, ' ')
  .trim()
  .slice(0, 2000);

const prompt = [
  'Business Name: ' + (it.business_name || 'Unknown'),
  'Category: ' + (it.category || 'N/A'),
  'Location: ' + (it.city || 'N/A'),
  'Website: ' + (it.website_url || 'N/A'),
  'Contact Email: ' + (it.email || 'N/A'),
  '',
  'Performance Scores (0-100):',
  '  PageSpeed: ' + (it.pagespeed_score ?? 'unknown'),
  '  SEO: ' + (it.seo_score ?? 'unknown'),
  '  Mobile/Accessibility: ' + (it.mobile_score ?? 'unknown'),
  '',
  'Detected Pain Points:',
  pains.length ? pains.map(p => '  - ' + p).join('\n') : '  - None auto-detected',
  '',
  'Website Content Snippet (first 2000 chars):',
  htmlSnippet || '(no scraped content available — use scores and pain points only)'
].join('\n');

const systemPrompt = `You are an expert web consultant and cold email copywriter.

You will receive data about a local business website. Your job is to:
1. Write a short, honest audit (3-4 bullet points) of what is wrong with their site
2. Write a personalized cold email (under 150 words) that:
   - Addresses the owner by business name
   - Mentions 1-2 specific problems you found
   - Offers to help fix them
   - Has a soft CTA (short call, quick chat)
   - Does NOT sound spammy or templated

Return ONLY valid JSON in this format:
{
  "audit_summary": "...",
  "email_subject": "...",
  "email_body": "..."
}`;

return {
  id: it.id,
  business_name: it.business_name,
  email: it.email,
  retry_count: it.retry_count,
  prompt,
  systemPrompt,
  openaiModel: cfg.openaiModel,
  maxRetries: cfg.maxRetries
};

// Call OpenAI GPT-4o with retries + JSON parse — 2026-06-19 UTC+5
const it = $json;
const apiKey = $env.OPENAI_API_KEY;
const http = this.helpers.httpRequest;

const base = {
  id: it.id,
  business_name: it.business_name,
  email: it.email,
  retry_count: it.retry_count,
  parse_ok: false,
  audit_summary: null,
  email_subject: null,
  personalized_email: null,
  failure_reason: null
};

if (!apiKey) {
  return { ...base, failure_reason: 'missing OPENAI_API_KEY env var' };
}

const body = {
  model: it.openaiModel || 'gpt-4o',
  response_format: { type: 'json_object' },
  temperature: 0.7,
  messages: [
    { role: 'system', content: it.systemPrompt },
    { role: 'user', content: it.prompt }
  ]
};

let raw = null;
let lastErr = null;

for (let attempt = 1; attempt <= 2; attempt++) {
  try {
    const res = await http({
      method: 'POST',
      url: 'https://api.openai.com/v1/chat/completions',
      headers: {
        Authorization: 'Bearer ' + apiKey,
        'Content-Type': 'application/json'
      },
      body,
      json: true,
      timeout: 120000
    });
    raw = res?.choices?.[0]?.message?.content ?? null;
    if (raw) break;
    lastErr = 'empty OpenAI response';
  } catch (e) {
    lastErr = e.message || String(e);
    if (attempt < 2) await new Promise(r => setTimeout(r, 2000));
  }
}

if (!raw) {
  return { ...base, failure_reason: lastErr || 'openai call failed' };
}

try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  const parsed = JSON.parse(cleaned);

  const audit = (parsed.audit_summary || '').trim();
  const subject = (parsed.email_subject || '').trim();
  const bodyText = (parsed.email_body || parsed.personalized_email || '').trim();

  if (!audit || !subject || !bodyText) {
    return {
      ...base,
      failure_reason: 'OpenAI JSON missing required fields (audit_summary, email_subject, email_body)'
    };
  }

  if (subject.length > 500) {
    return { ...base, failure_reason: 'email_subject exceeds 500 characters' };
  }

  return {
    ...base,
    parse_ok: true,
    audit_summary: audit,
    email_subject: subject,
    personalized_email: bodyText,
    failure_reason: null
  };
} catch (e) {
  return { ...base, failure_reason: 'invalid JSON from OpenAI: ' + (e.message || String(e)) };
}

// Aggregate run stats for workflow_logs — 2026-06-19 UTC+5
const cfg = $('config').first().json;
const aiItems = $('Call OpenAI & Parse').all();
const success = aiItems.filter(i => i.json.parse_ok).length;
const failed = aiItems.length - success;
const leadIds = aiItems.map(i => i.json.id).join(',');
const start = new Date(cfg.runStartTs).getTime();
const durationMs = Number.isFinite(start) ? Date.now() - start : 0;

return [{
  json: {
    workflow_name: cfg.workflowName,
    leads_processed: success,
    leads_failed: failed,
    duration_ms: durationMs,
    notes: 'batch_ids: ' + (leadIds || 'none')
  }
}];

// Normalize node-level error output before DB recovery — 2026-06-19 UTC+5
const it = $input.item.json;
const errMsg = it.error?.message || it.failure_reason || 'workflow crash during audit';
return {
  id: it.id,
  failure_reason: errMsg
};
